<template>
  <section class="access-page" dir="rtl"><header><div><h1>مدیریت دسترسی مدیران</h1><p>تنها مالک یا مدیر ارشد می‌تواند سطح دسترسی مدیران را تغییر دهد.</p></div></header><form @submit.prevent="load" class="filters"><input v-model.trim="search" placeholder="جستجوی نام یا شماره تلفن"/><button>جستجو</button></form><div v-if="error" class="error">{{error}}</div><div class="admin-list"><article v-for="admin in admins" :key="admin.id"><div><strong>{{admin.fullname}}</strong><span>{{admin.phone_number}}</span></div><label>سطح دسترسی<select :value="admin.admin_role" :disabled="saving===admin.id || admin.admin_role==='owner' && admin.is_superuser" @change="updateRole(admin,$event.target.value)"><option value="regular_admin">مدیر عادی</option><option value="owner">مالک / مدیر ارشد</option></select></label><span :class="['role',admin.admin_role]">{{admin.admin_role==='owner'?'مدیر ارشد':'مدیر عادی'}}</span></article><p v-if="!admins.length && !loading">مدیری یافت نشد.</p></div><footer v-if="pages>1"><button :disabled="page===1" @click="page--;load()">قبلی</button><span>صفحه {{page}} از {{pages}}</span><button :disabled="page===pages" @click="page++;load()">بعدی</button></footer><CostToastHost/></section>
</template>
<script setup>
import { onMounted, ref } from 'vue'
import authApi from '@/api/auth.api'
import { useCostToast } from '@/composables/useCostToast'
import CostToastHost from '@/components/cost/CostToastHost.vue'
import { getApiErrorMessage } from '@/api/error'
const admins=ref([]), search=ref(''), page=ref(1), pages=ref(1), loading=ref(false), saving=ref(null), error=ref(''); const toast=useCostToast()
async function load(){loading.value=true;error.value='';try{const {data}=await authApi.getAdminUsers({search:search.value,page:page.value,page_size:10});if(!data.success)throw new Error(data.message);admins.value=data.data.results;pages.value=data.data.total_pages;page.value=data.data.page}catch(cause){error.value=getApiErrorMessage(cause,'دریافت مدیران امکان‌پذیر نیست.')}finally{loading.value=false}}
async function updateRole(admin,role){saving.value=admin.id;try{const {data}=await authApi.updateAdminRole(admin.id,role);if(!data.success)throw new Error(data.message);admin.admin_role=data.data.admin_role;toast.success(data.message)}catch(cause){toast.error(getApiErrorMessage(cause,'به‌روزرسانی دسترسی ناموفق بود.'))}finally{saving.value=null}}
onMounted(load)
</script>
<style scoped>.access-page{display:grid;gap:1rem}.access-page h1{margin:0;color:var(--text);font-size:1.45rem}.access-page p{color:var(--muted)}.filters,.admin-list{padding:1rem;background:var(--surface);border:1px solid var(--border);border-radius:14px}.filters{display:flex;gap:.6rem}.filters input,.filters button,select,footer button{min-height:40px;border:1px solid var(--border-strong);border-radius:8px;background:var(--input);color:var(--text);padding:.5rem .7rem;font:inherit}.filters input{flex:1}.filters button{background:var(--primary);border-color:var(--primary);color:#fff}.admin-list article{display:flex;align-items:center;gap:1rem;padding:.8rem 0;border-bottom:1px solid var(--border)}.admin-list article>div{display:grid;gap:.25rem;flex:1}.admin-list span{color:var(--muted);font-size:.85rem}.admin-list label{display:grid;gap:.3rem;color:var(--muted);font-size:.8rem}.role{padding:.3rem .55rem;border-radius:99px;background:var(--surface-subtle)}.role.owner{background:#ede9fe;color:#6d28d9}.error{padding:.8rem;border-radius:8px;background:#fee2e2;color:#b91c1c}footer{display:flex;justify-content:center;align-items:center;gap:1rem;color:var(--muted)}@media(max-width:620px){.admin-list article{align-items:flex-start;flex-direction:column}.admin-list label,select{width:100%}}</style>
